export type Easing = (t: number) => number;

/** No acceleration: constant speed. */
export const linear: Easing = (t) => t;

/** Accelerating from rest (quadratic). */
export const easeInQuad: Easing = (t) => t * t;

/** Decelerating to rest (quadratic). */
export const easeOutQuad: Easing = (t) => 1 - (1 - t) * (1 - t);

/** Slow start and end, fast middle (cubic). */
export const easeInOutCubic: Easing = (t) =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

export class Tween {
  readonly startValue: number;
  readonly endValue: number;
  readonly durationTicks: number;
  readonly easing: Easing;
  /** Fires when the tween reaches its end value. */
  onComplete?: () => void;

  private elapsed = 0;
  private _done = false;
  private chainedTween: Tween | null = null;

  constructor(
    start: number,
    end: number,
    durationTicks: number,
    easing: Easing = linear
  ) {
    if (durationTicks <= 0) throw new Error("durationTicks must be > 0");
    this.startValue = start;
    this.endValue = end;
    this.durationTicks = durationTicks;
    this.easing = easing;
  }

  get done(): boolean {
    return this._done;
  }

  /** Current interpolated value; clamps at end once finished. */
  get value(): number {
    const clamped = Math.min(this.elapsed, this.durationTicks);
    return (
      this.startValue +
      (this.endValue - this.startValue) * this.easing(clamped / this.durationTicks)
    );
  }

  /**
   * Advance one tick. When the tween completes, the chained tween
   * (if any) starts advancing from this same tick onward.
   */
  tick(): void {
    if (!this._done) {
      this.elapsed++;
      if (this.elapsed >= this.durationTicks) {
        this._done = true;
        this.onComplete?.();
      }
    }
    if (this.chainedTween && !this.chainedTween.done) {
      this.chainedTween.tick();
    }
  }

  /** Queue a tween that starts ticking only after this one completes. */
  chain(next: Tween): Tween {
    this.chainedTween = next;
    return next;
  }

  reset(): void {
    this.elapsed = 0;
    this._done = false;
  }
}

