import { describe, it, expect } from "vitest";
import {
  linear,
  easeInQuad,
  easeOutQuad,
  easeInOutCubic,
  Tween,
} from "../src/tween";

describe("easings", () => {
  const easings: [string, (t: number) => number][] = [
    ["linear", linear],
    ["easeInQuad", easeInQuad],
    ["easeOutQuad", easeOutQuad],
    ["easeInOutCubic", easeInOutCubic],
  ];

  it("map 0 -> 0 and 1 -> 1", () => {
    for (const [name, fn] of easings) {
      expect(fn(0), name).toBe(0);
      expect(fn(1), name).toBe(1);
    }
  });

  it("easeInOutCubic(0.5) === 0.5", () => {
    expect(easeInOutCubic(0.5)).toBe(0.5);
  });

  it("easeOutQuad(0.25) === 0.4375", () => {
    expect(easeOutQuad(0.25)).toBe(0.4375);
  });
});

describe("Tween", () => {
  it("10-tick tween from 0 to 100 with linear easing reads exactly 50 after 5 ticks", () => {
    const tween = new Tween(0, 100, 10, linear);
    for (let i = 0; i < 5; i++) tween.tick();
    expect(tween.value).toBe(50);
    expect(tween.done).toBe(false);
  });

  it("clamps at end value and reports done when complete", () => {
    const tween = new Tween(0, 100, 10, linear);
    for (let i = 0; i < 20; i++) tween.tick(); // overshoot ticks
    expect(tween.done).toBe(true);
    expect(tween.value).toBe(100); // exact clamp, no float drift
  });

  it("chaining fires second tween exactly when first completes", () => {
    let firedAtTick = -1;
    let currentTick = 0;

    const second = new Tween(0, 1, 3, linear);
    second.onComplete = () => {
      firedAtTick = currentTick;
    };

    const first = new Tween(0, 100, 5, linear);
    first.chain(second);

    for (currentTick = 1; currentTick <= 8; currentTick++) first.tick();

    // first completes at tick 5 -> second starts same tick and completes at tick 8
    expect(firedAtTick).toBe(8);
    expect(first.done).toBe(true);
    expect(first.value).toBe(100);
    expect(second.done).toBe(true);
  });

  it("second tween does not advance before first completes", () => {
    const second = new Tween(0, 3, 3, linear);
    const first = new Tween(0, 100, 4, linear).chain(second);

    for (let i = 0; i < 3; i++) first.tick();
    expect(second.value).toBe(0); // untouched until first is done
    expect(first.done).toBe(false);

    first.tick(); // tick 4: first completes, second gets its first tick
    expect(first.done).toBe(true);
    expect(second.value).toBe(1); // exactly 1 of its 3 ticks elapsed
  });
});

